#include <stdio.h>

void append(char *dest, const char *src) {
    int end = 0;
    while (dest[end] != '\0') {
        end++;
    }
    int i = 0;
    while (src[i] != '\0') {
        dest[end + i] = src[i];
        i++;
    }
    dest[end + i] = '\0';
}

int main() {
    char text[30] = "Code";
    append(text, "Varsity");
    printf("%s\n", text);
    return 0;
}
